{
  "version": "0.2",
  "phases": {
    "build": {
      "commands": [
        "python -m pip install --upgrade pip",
        "pip install -r requirements.txt",
        "cdk synth"
      ]
    }
  },
  "artifacts": {
    "base-directory": "cdk.out",
    "files": "**/*"
  }
}

